<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>SNAKE — GRID RUNNER</title>
<style>
  :root{
    --bg:#0a0c08; --panel:#0d110a; --board:#0c100a;
    --line:#20281a; --text:#e2ead6; --muted:#7c8770;
    --accent:#b8ef4e; --accent-hi:#d3f97e; --food:#ff6a4d;
    --danger:#ff5546; --amber:#ffc453;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{height:100%}
  body{
    background:var(--bg); color:var(--text);
    font-family:ui-monospace,"Cascadia Code","SF Mono","JetBrains Mono",Menlo,Consolas,"Liberation Mono",monospace;
    display:flex; align-items:center; justify-content:center;
    min-height:100vh; padding:28px 16px;
    -webkit-font-smoothing:antialiased; user-select:none;
  }
  .wrap{width:min(542px,100%)}

  /* ---------- header ---------- */
  .top{display:flex; justify-content:space-between; align-items:flex-end; gap:16px; margin-bottom:16px}
  .brand{display:flex; align-items:center; gap:12px}
  .brand svg{display:block; flex:none}
  h1{font-size:26px; font-weight:700; letter-spacing:.34em; line-height:1}
  h1 .cursor{color:var(--accent); animation:blink 1.1s steps(1) infinite}
  @keyframes blink{50%{opacity:0}}
  .tag{font-size:9px; letter-spacing:.32em; color:var(--muted); margin-top:6px; text-transform:uppercase}
  .stats{display:flex; gap:22px}
  .stat{text-align:right}
  .stat .label{display:block; font-size:9px; letter-spacing:.26em; color:var(--muted); text-transform:uppercase; margin-bottom:4px}
  .stat .value{display:block; font-size:22px; font-weight:700; line-height:1; font-variant-numeric:tabular-nums}
  #score{color:var(--accent)}
  .value.pop{animation:pop .3s ease}
  @keyframes pop{40%{transform:scale(1.3)}}

  /* ---------- board frame ---------- */
  .frame{position:relative; border:1px solid var(--line); background:var(--panel); padding:10px; transition:border-color .45s ease}
  .frame.hit{border-color:var(--danger); transition:border-color .05s ease}
  .frame.shake{animation:shake .34s linear}
  @keyframes shake{
    12%{transform:translate(-6px,2px)} 28%{transform:translate(5px,-3px)}
    46%{transform:translate(-4px,2px)} 64%{transform:translate(3px,-2px)}
    82%{transform:translate(-2px,1px)}
  }
  .corner{position:absolute; width:14px; height:14px; border:2px solid var(--accent); pointer-events:none}
  .corner.tl{top:-2px; left:-2px; border-right:0; border-bottom:0}
  .corner.tr{top:-2px; right:-2px; border-left:0; border-bottom:0}
  .corner.bl{bottom:-2px; left:-2px; border-right:0; border-top:0}
  .corner.br{bottom:-2px; right:-2px; border-left:0; border-top:0}
  canvas{display:block; width:max(400px,100%); aspect-ratio:1/1; background:var(--board); touch-action:none}

  /* ---------- status + controls ---------- */
  .statusbar{display:flex; justify-content:space-between; align-items:center; margin-top:14px;
             font-size:10px; letter-spacing:.2em; color:var(--muted); text-transform:uppercase}
  .status{display:flex; align-items:center; gap:8px; color:var(--text)}
  .dot{width:8px; height:8px; border-radius:50%; background:var(--muted); flex:none}
  .dot.running{background:var(--accent); animation:pulse 1s ease-in-out infinite}
  .dot.paused{background:var(--amber)}
  .dot.over{background:var(--danger)}
  @keyframes pulse{50%{opacity:.3}}
  .controls{display:flex; gap:10px; margin-top:14px}
  .btn{flex:1; appearance:none; background:transparent; border:1px solid var(--line); color:var(--text);
       font-family:inherit; font-size:11px; font-weight:700; letter-spacing:.24em; text-transform:uppercase;
       padding:13px 0 12px; cursor:pointer;
       transition:border-color .15s, color .15s, background .15s, transform .05s}
  .btn:hover:not(:disabled){border-color:var(--accent); color:var(--accent)}
  .btn:active:not(:disabled){transform:translateY(1px)}
  .btn:focus-visible{outline:2px solid var(--accent); outline-offset:2px}
  .btn:disabled{opacity:.35; cursor:default}
  .btn.primary{background:var(--accent); border-color:var(--accent); color:#0b1005}
  .btn.primary:hover:not(:disabled){background:var(--accent-hi); border-color:var(--accent-hi); color:#0b1005}
  .btn.ghost{flex:0 0 auto; padding:13px 14px 12px; font-size:9px; color:var(--muted)}
  .btn.ghost:hover:not(:disabled){color:var(--text); border-color:var(--muted)}
  .foot{margin-top:18px; text-align:center; font-size:9px; letter-spacing:.3em; color:#4c5543; text-transform:uppercase}
</style>
</head>
<body>
<main class="wrap">

  <header class="top">
    <div class="brand">
      <svg width="30" height="30" viewBox="0 0 24 24" fill="none" aria-hidden="true">
        <path d="M20 3.5H7.5V12H16v8.5H4" stroke="#b8ef4e" stroke-width="3.4" stroke-linecap="square"/>
        <circle cx="20" cy="20.5" r="2.4" fill="#ff6a4d"/>
      </svg>
      <div>
        <h1>SNAKE<span class="cursor">_</span></h1>
        <p class="tag">grid runner · 20×20</p>
      </div>
    </div>
    <div class="stats">
      <div class="stat"><span class="label">Score</span><span class="value" id="score">0</span></div>
      <div class="stat"><span class="label">Best</span><span class="value" id="best">0</span></div>
      <div class="stat"><span class="label">Length</span><span class="value" id="len">3</span></div>
    </div>
  </header>

  <div class="frame" id="frame">
    <i class="corner tl"></i><i class="corner tr"></i><i class="corner bl"></i><i class="corner br"></i>
    <canvas id="snake" width="520" height="520" aria-label="Snake game board"></canvas>
  </div>

  <div class="statusbar">
    <div class="status"><i class="dot" id="dot"></i><span id="statusText" aria-live="polite">READY</span></div>
    <div>&larr;&uarr;&darr;&rarr; steer&ensp;·&ensp;space pause</div>
  </div>

  <div class="controls">
    <button id="start"  class="btn primary" type="button">START</button>
    <button id="pause"  class="btn"         type="button" disabled>PAUSE</button>
    <button id="reset"  class="btn"         type="button">RESET</button>
    <button id="sound"  class="btn ghost"   type="button" aria-pressed="true">SND ON</button>
  </div>

  <footer class="foot">walls are fatal · so is your own tail</footer>
</main>

<script>
(() => {
'use strict';

/* ============================== config ============================== */
const COLS = 20, ROWS = 20;               // grid: 20 x 20 cells (>= 10 required)
const BASE_MS = 150, MIN_MS = 70;         // tick speed, ramps up with score
const MONO = 'ui-monospace,"Cascadia Code","SF Mono",Menlo,Consolas,monospace';

/* ================================ dom =============================== */
const $ = id => document.getElementById(id);
const canvas = $('snake'), ctx = canvas.getContext('2d');
const scoreEl = $('score'), bestEl = $('best'), lenEl = $('len');
const startBtn = $('start'), pauseBtn = $('pause'), resetBtn = $('reset'), soundBtn = $('sound');
const dotEl = $('dot'), statusEl = $('statusText'), frameEl = $('frame');

/* =============================== state ============================== */
let snakeArr = [];        // logical cells, HEAD FIRST: [{x,y}, ...]
let prevArr = [];         // snapshot before the last tick (used for smooth rendering)
let dir = 'right';        // current heading
let dirQueue = [];        // buffered turns
let foodPos = { x: 14, y: 10 };
let scoreVal = 0, bestVal = 0;
let aliveFlag = true, winFlag = false;
let state = 'idle';       // idle | running | paused | over
let deathCause = '';
let stepMs = BASE_MS, lastStepAt = 0;
let acc = 0, lastFrame = 0;
let effects = [], deathFlash = 0;

try { bestVal = parseInt(localStorage.getItem('snake-best'), 10) || 0; } catch (_) {}
function saveBest(){ try { localStorage.setItem('snake-best', String(bestVal)); } catch (_) {} }

/* ============================== helpers ============================= */
const DIRS = { up:{x:0,y:-1}, down:{x:0,y:1}, left:{x:-1,y:0}, right:{x:1,y:0} };
const OPP  = { up:'down', down:'up', left:'right', right:'left' };
const cellKey = (x, y) => y * COLS + x;
const same = (a, b) => a.x === b.x && a.y === b.y;
const cloneSegs = s => s.map(p => ({ x: p.x, y: p.y }));
const lerp = (a, b, t) => a + (b - a) * t;

/* ============================ tiny synth ============================ */
const sfx = (() => {
  let ac = null, master = null, on = true;
  try { on = localStorage.getItem('snake-snd') !== 'off'; } catch (_) {}
  function ensure(){
    if (ac){ if (ac.state === 'suspended') ac.resume(); return; }
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      ac = new AC();
      master = ac.createGain(); master.gain.value = 0.5; master.connect(ac.destination);
    } catch (_) {}
  }
  function tone(f0, f1, dur, type, vol, delay){
    if (!ac || !on) return;
    const t0 = ac.currentTime + (delay || 0);
    const o = ac.createOscillator(), g = ac.createGain();
    o.type = type; o.frequency.setValueAtTime(f0, t0);
    if (f1 !== f0) o.frequency.exponentialRampToValueAtTime(Math.max(1, f1), t0 + dur);
    g.gain.setValueAtTime(vol, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    o.connect(g); g.connect(master);
    o.start(t0); o.stop(t0 + dur + 0.02);
  }
  return {
    ensure,
    get on(){ return on; },
    toggle(){ on = !on; try { localStorage.setItem('snake-snd', on ? 'on' : 'off'); } catch (_){} if (on) ensure(); return on; },
    eat(){ tone(520, 880, 0.12, 'square', 0.16); tone(880, 1320, 0.10, 'square', 0.10, 0.06); },
    die(){ tone(300, 55, 0.42, 'sawtooth', 0.22); tone(160, 40, 0.50, 'triangle', 0.18, 0.03); },
    start(){ tone(330, 660, 0.14, 'triangle', 0.14); },
    pause(){ tone(440, 330, 0.09, 'triangle', 0.10); },
    blip(){ tone(500, 380, 0.07, 'triangle', 0.08); }
  };
})();
const ensureAudio = () => sfx.ensure();

/* ========================== canvas sizing =========================== */
let cssSize = 520, cell = 26;
function fit(){
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  cssSize = canvas.clientWidth || 520;
  const px = Math.round(cssSize * dpr);
  if (canvas.width !== px){ canvas.width = px; canvas.height = px; }
  cell = cssSize / COLS;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
window.addEventListener('resize', () => { fit(); draw(performance.now()); });

/* ========================= core game logic ========================== */
function spawnFood(){
  const occ = new Set(snakeArr.map(p => cellKey(p.x, p.y)));
  const free = [];
  for (let y = 0; y < ROWS; y++)
    for (let x = 0; x < COLS; x++)
      if (!occ.has(cellKey(x, y))) free.push({ x, y });
  if (!free.length){ winFlag = true; return; }   // board completely filled
  foodPos = free[(Math.random() * free.length) | 0];
}

function reset(){
  const cy = ROWS >> 1, hx = (COLS >> 1) - 2;
  snakeArr = [{ x: hx, y: cy }, { x: hx - 1, y: cy }, { x: hx - 2, y: cy }];  // length 3, head first
  prevArr = cloneSegs(snakeArr);
  dir = 'right'; dirQueue = [];
  scoreVal = 0; aliveFlag = true; winFlag = false; deathCause = '';
  stepMs = BASE_MS; effects = []; deathFlash = 0; acc = 0;
  spawnFood();
  state = 'idle';
  syncUI();
}

function setDir(d){
  if (!(d in DIRS)) return;
  const eff = dirQueue.length ? dirQueue[dirQueue.length - 1] : dir;
  if (d === eff || d === OPP[eff]) return;      // repeats & 180° reversals are ignored
  if (dirQueue.length < 3) dirQueue.push(d);
}

function tick(){
  if (!aliveFlag) return;

  // consume one queued turn (re-validating against the live heading)
  while (dirQueue.length){
    const d = dirQueue.shift();
    if (d !== dir && d !== OPP[dir]){ dir = d; break; }
  }

  prevArr = cloneSegs(snakeArr);                // snapshot for interpolation

  const v = DIRS[dir];
  const head = { x: snakeArr[0].x + v.x, y: snakeArr[0].y + v.y };

  // wall collision ends the game
  if (head.x < 0 || head.y < 0 || head.x >= COLS || head.y >= ROWS) return die('wall');

  // self collision ends the game (the tail tip vacates unless we grow this step)
  const grow = same(head, foodPos);
  const lim = snakeArr.length - (grow ? 0 : 1);
  for (let i = 0; i < lim; i++) if (same(head, snakeArr[i])) return die('self');

  snakeArr.unshift(head);
  if (grow){
    scoreVal++;
    if (scoreVal > bestVal){ bestVal = scoreVal; saveBest(); }
    stepMs = Math.max(MIN_MS, BASE_MS - scoreVal * 3);   // gentle speed ramp
    const now = performance.now();
    effects.push({ type: 'ring', x: head.x, y: head.y, born: now });
    effects.push({ type: 'text', x: head.x, y: head.y, born: now });
    popScore();
    sfx.eat();
    spawnFood();
    if (winFlag) return die('win');
  } else {
    snakeArr.pop();
  }
  lastStepAt = performance.now();
  syncUI();
}

function die(cause){
  aliveFlag = false;
  deathCause = cause;
  state = 'over';
  prevArr = cloneSegs(snakeArr);                // freeze the pose
  deathFlash = performance.now();
  frameEl.classList.remove('shake'); void frameEl.offsetWidth;
  frameEl.classList.add('shake', 'hit');
  setTimeout(() => frameEl.classList.remove('hit'), 420);
  saveBest();
  sfx.die();
  syncUI();
}

/* ============================ ui syncing ============================ */
function syncUI(){
  scoreEl.textContent = scoreVal;
  bestEl.textContent = bestVal;
  lenEl.textContent = snakeArr.length;

  let txt = 'READY', cls = '';
  if (state === 'running'){ txt = 'RUNNING'; cls = 'running'; }
  else if (state === 'paused'){ txt = 'PAUSED'; cls = 'paused'; }
  else if (state === 'over'){
    txt = deathCause === 'wall' ? 'GAME OVER — WALL'
        : deathCause === 'self' ? 'GAME OVER — SELF'
        : deathCause === 'win'  ? 'PERFECT CLEAR' : 'GAME OVER';
    cls = 'over';
  }
  statusEl.textContent = txt;
  dotEl.className = 'dot' + (cls ? ' ' + cls : '');

  startBtn.disabled = state === 'running';
  startBtn.textContent = state === 'over' ? 'RETRY' : state === 'paused' ? 'RESUME' : 'START';
  pauseBtn.disabled = !(state === 'running' || state === 'paused');
  pauseBtn.textContent = state === 'paused' ? 'RESUME' : 'PAUSE';
}

function popScore(){
  scoreEl.classList.remove('pop'); void scoreEl.offsetWidth;
  scoreEl.classList.add('pop');
}

/* ============================= controls ============================= */
function startRun(){
  ensureAudio();
  if (state === 'over') reset();
  if (state === 'running') return;
  state = 'running';
  lastFrame = performance.now(); acc = 0;
  sfx.start();
  syncUI();
}
function pauseToggle(){
  if (state === 'running'){
    state = 'paused';
    prevArr = cloneSegs(snakeArr);              // freeze mid-step cleanly
    sfx.pause(); syncUI();
  } else if (state === 'paused'){
    state = 'running';
    lastFrame = performance.now(); acc = 0;
    sfx.pause(); syncUI();
  }
}
startBtn.addEventListener('click', e => { startRun(); e.currentTarget.blur(); });
pauseBtn.addEventListener('click', e => { pauseToggle(); e.currentTarget.blur(); });
resetBtn.addEventListener('click', e => { reset(); sfx.blip(); e.currentTarget.blur(); });

function syncSoundBtn(){
  soundBtn.textContent = sfx.on ? 'SND ON' : 'SND OFF';
  soundBtn.setAttribute('aria-pressed', String(sfx.on));
}
soundBtn.addEventListener('click', e => { sfx.toggle(); syncSoundBtn(); e.currentTarget.blur(); });

/* ============================== input =============================== */
const KEYMAP = {
  ArrowUp:'up', ArrowDown:'down', ArrowLeft:'left', ArrowRight:'right',
  KeyW:'up', KeyS:'down', KeyA:'left', KeyD:'right'
};
window.addEventListener('keydown', e => {
  const d = KEYMAP[e.code];
  if (d){
    e.preventDefault();
    ensureAudio();
    if (state === 'idle') startRun();           // steering from the ready screen just starts
    if (state !== 'over') setDir(d);
    return;
  }
  if (e.target && e.target.tagName === 'BUTTON') return;   // let focused buttons take Enter/Space
  if (e.code === 'Space' || e.code === 'Enter'){
    e.preventDefault();
    ensureAudio();
    if (state === 'idle' || state === 'over') startRun();
    else pauseToggle();
  }
});

/* touch: swipe steers, tap pauses / starts */
let touchStart = null;
canvas.addEventListener('touchstart', e => { touchStart = e.changedTouches[0]; }, { passive: true });
canvas.addEventListener('touchend', e => {
  if (!touchStart) return;
  const t = e.changedTouches[0];
  const dx = t.clientX - touchStart.clientX, dy = t.clientY - touchStart.clientY;
  touchStart = null;
  ensureAudio();
  if (Math.hypot(dx, dy) < 24){
    if (state === 'running' || state === 'paused') pauseToggle(); else startRun();
    return;
  }
  if (state === 'idle') startRun();
  if (state !== 'over')
    setDir(Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left')
                                       : (dy > 0 ? 'down' : 'up'));
}, { passive: true });

/* ============================ main loop ============================= */
function loop(now){
  requestAnimationFrame(loop);
  if (state === 'running'){
    if (!lastFrame) lastFrame = now;
    acc += Math.min(now - lastFrame, 250);      // clamp so a hidden tab can't death-spiral
    lastFrame = now;
    let guard = 0;
    while (acc >= stepMs && state === 'running' && guard++ < 8){
      acc -= stepMs;
      tick();
    }
    if (state !== 'running') acc = 0;
  } else {
    lastFrame = now;
  }
  draw(now);
}

/* ============================ rendering ============================= */
function draw(now){
  ctx.clearRect(0, 0, cssSize, cssSize);
  drawBoard();
  drawFood(now);
  drawRings(now);
  drawSnake(now);
  drawFloats(now);
  drawOverlays(now);
}

function drawBoard(){
  ctx.fillStyle = 'rgba(255,255,255,0.016)';    // whisper-quiet checkerboard
  for (let y = 0; y < ROWS; y++)
    for (let x = 0; x < COLS; x++)
      if ((x + y) & 1) ctx.fillRect(x * cell, y * cell, cell, cell);
  ctx.strokeStyle = 'rgba(226,234,214,0.06)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let i = 1; i < COLS; i++){ const p = i * cell; ctx.moveTo(p, 0); ctx.lineTo(p, cssSize); }
  for (let j = 1; j < ROWS; j++){ const p = j * cell; ctx.moveTo(0, p); ctx.lineTo(cssSize, p); }
  ctx.stroke();
}

function drawFood(now){
  const cx = (foodPos.x + .5) * cell, cy = (foodPos.y + .5) * cell;
  const r = cell * 0.30 * (1 + Math.sin(now / 190) * 0.07);   // gentle breathing
  ctx.fillStyle = 'rgba(0,0,0,.35)';
  ctx.beginPath(); ctx.ellipse(cx, cy + r * .8, r * .8, r * .35, 0, 0, 7); ctx.fill();
  ctx.fillStyle = '#ff6a4d';
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, 7); ctx.fill();
  ctx.fillStyle = 'rgba(255,236,226,.55)';
  ctx.beginPath(); ctx.arc(cx - r * .3, cy - r * .35, r * .24, 0, 7); ctx.fill();
  ctx.strokeStyle = '#7d4a2b'; ctx.lineWidth = Math.max(1.5, cell * .07); ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(cx + r * .05, cy - r * .85);
  ctx.quadraticCurveTo(cx + r * .1, cy - r * 1.4, cx + r * .55, cy - r * 1.45); ctx.stroke();
  ctx.fillStyle = '#8fc94b';
  ctx.beginPath(); ctx.ellipse(cx + r * .8, cy - r * 1.3, r * .38, r * .17, -.55, 0, 7); ctx.fill();
}

function bodyColor(f){
  const a = aliveFlag ? [201, 247, 111] : [128, 135, 119];
  const b = aliveFlag ? [56, 118, 41]   : [64, 70, 60];
  return 'rgb(' + Math.round(lerp(a[0], b[0], f)) + ',' +
                  Math.round(lerp(a[1], b[1], f)) + ',' +
                  Math.round(lerp(a[2], b[2], f)) + ')';
}

function drawSnake(now){
  const t = Math.max(0, Math.min(1, (now - lastStepAt) / stepMs));  // glide between ticks
  const n = snakeArr.length;
  const pts = new Array(n);
  for (let i = 0; i < n; i++){
    const c = snakeArr[i];
    const p = prevArr[Math.min(i, prevArr.length - 1)] || c;
    pts[i] = { x: (lerp(p.x, c.x, t) + .5) * cell, y: (lerp(p.y, c.y, t) + .5) * cell };
  }

  ctx.lineCap = 'round'; ctx.lineJoin = 'round';

  // dark halo separates the snake from the grid
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < n; i++) ctx.lineTo(pts[i].x, pts[i].y);
  ctx.strokeStyle = 'rgba(4,7,3,.85)';
  ctx.lineWidth = cell * .8;
  ctx.stroke();

  // body painted tail -> head, bright chartreuse fading into deep green
  ctx.lineWidth = cell * .64;
  for (let i = n - 1; i > 0; i--){
    ctx.strokeStyle = bodyColor(n > 1 ? i / (n - 1) : 0);
    ctx.beginPath();
    ctx.moveTo(pts[i].x, pts[i].y);
    ctx.lineTo(pts[i - 1].x, pts[i - 1].y);
    ctx.stroke();
  }

  // head + eyes that look where it's going
  const hp = pts[0];
  ctx.fillStyle = aliveFlag ? '#d6fa85' : '#a7ae9d';
  ctx.beginPath(); ctx.arc(hp.x, hp.y, cell * .4, 0, 7); ctx.fill();
  drawEyes(hp);
}

function drawEyes(hp){
  const v = DIRS[dir], px = -v.y, py = v.x;
  const fwd = cell * .13, side = cell * .155, er = cell * .105, pr = cell * .05;
  for (const s of [-1, 1]){
    const ex = hp.x + v.x * fwd + px * side * s;
    const ey = hp.y + v.y * fwd + py * side * s;
    if (aliveFlag){
      ctx.fillStyle = '#0d130a';
      ctx.beginPath(); ctx.arc(ex, ey, er, 0, 7); ctx.fill();
      ctx.fillStyle = '#eafbd0';
      ctx.beginPath(); ctx.arc(ex + v.x * pr * .9, ey + v.y * pr * .9, pr, 0, 7); ctx.fill();
    } else {
      ctx.strokeStyle = '#ffd9d4'; ctx.lineWidth = Math.max(1.5, cell * .06); ctx.lineCap = 'round';
      const k = er * .9;
      ctx.beginPath();
      ctx.moveTo(ex - k, ey - k); ctx.lineTo(ex + k, ey + k);
      ctx.moveTo(ex + k, ey - k); ctx.lineTo(ex - k, ey + k);
      ctx.stroke();
    }
  }
}

function drawRings(now){
  effects = effects.filter(fx => now - fx.born < (fx.type === 'ring' ? 450 : 750));
  for (const fx of effects){
    if (fx.type !== 'ring') continue;
    const p = (now - fx.born) / 450;
    ctx.strokeStyle = 'rgba(184,239,78,' + (0.8 * (1 - p)).toFixed(3) + ')';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc((fx.x + .5) * cell, (fx.y + .5) * cell, cell * (.3 + p * .8), 0, 7);
    ctx.stroke();
  }
}

function drawFloats(now){
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = '700 ' + Math.round(cell * .55) + 'px ' + MONO;
  for (const fx of effects){
    if (fx.type !== 'text') continue;
    const p = (now - fx.born) / 750;
    ctx.globalAlpha = 1 - p;
    ctx.fillStyle = '#d3f97e';
    ctx.fillText('+1', (fx.x + .5) * cell, (fx.y + .5) * cell - p * cell);
  }
  ctx.globalAlpha = 1;
}

function scrim(a){ ctx.fillStyle = 'rgba(6,9,4,' + a + ')'; ctx.fillRect(0, 0, cssSize, cssSize); }
function big(str, size, color, y, alpha){
  ctx.globalAlpha = alpha; ctx.fillStyle = color;
  ctx.font = '700 ' + size + 'px ' + MONO;
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText(str.split('').join(' '), cssSize / 2, y);
  ctx.globalAlpha = 1;
}
function small(str, y, color, alpha){
  ctx.globalAlpha = alpha; ctx.fillStyle = color;
  ctx.font = '700 12px ' + MONO;
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText(str, cssSize / 2, y);
  ctx.globalAlpha = 1;
}

function drawOverlays(now){
  if (deathFlash && now - deathFlash < 280){
    ctx.fillStyle = 'rgba(255,85,70,' + (0.22 * (1 - (now - deathFlash) / 280)).toFixed(3) + ')';
    ctx.fillRect(0, 0, cssSize, cssSize);
  }
  const cy = cssSize / 2;
  const blinkOn = ((now / 560) | 0) % 2 === 0;

  if (state === 'idle'){
    scrim(.55);
    big('READY', 40, '#e2ead6', cy - 16, 1);
    small('PRESS START — OR JUST STEER', cy + 26, '#b8ef4e', blinkOn ? 1 : .25);
  } else if (state === 'paused'){
    scrim(.55);
    big('PAUSED', 40, '#ffc453', cy - 16, 1);
    small('SPACE RESUMES', cy + 26, '#e2ead6', blinkOn ? 1 : .25);
  } else if (state === 'over'){
    scrim(.66);
    const win = deathCause === 'win';
    big(win ? 'PERFECT!' : 'GAME OVER', 42, win ? '#d3f97e' : '#ff6a4d', cy - 20, 1);
    small(win ? 'EVERY CELL FILLED'
             : deathCause === 'wall' ? 'THE WALL WINS THIS ROUND' : 'YOU BIT YOURSELF',
          cy + 18, '#cfd8c2', 1);
    small('SCORE ' + scoreVal + ' — ENTER TO RETRY', cy + 44, '#b8ef4e', blinkOn ? 1 : .25);
  }
}

/* ======================== programmatic API ========================== */
window.game = {
  get w(){ return COLS; },
  get h(){ return ROWS; },
  reset,                                     // fresh game: length 3, alive, score 0
  tick,                                      // advance exactly one step
  setDir,                                    // queue a turn; 180° reversals ignored
  setFood(x, y){                             // place food (clamped to the board) + redraw
    x = Math.floor(Number(x)); y = Math.floor(Number(y));
    if (!Number.isFinite(x) || !Number.isFinite(y)) return;
    foodPos = { x: Math.min(COLS - 1, Math.max(0, x)),
                y: Math.min(ROWS - 1, Math.max(0, y)) };
    winFlag = false;
    draw(performance.now());
  },
  snake(){ return snakeArr.map(p => [p.x, p.y]); },   // head first
  food(){ return [foodPos.x, foodPos.y]; },
  alive(){ return aliveFlag; },
  score(){ return scoreVal; }
};

/* =============================== boot =============================== */
syncSoundBtn();
fit();
reset();
requestAnimationFrame(loop);
})();
